using System.ComponentModel;
using Microsoft.Extensions.AI;

// --- Tool Definitions ---

var notes = new List<string>();

[Description("Search the web for information on a given query. Returns a list of relevant snippets.")]
string WebSearch([Description("The search query")] string query)
{
    // Simulated web search results for demonstration purposes.
    // In production, replace with a real search API (e.g., Bing Search).
    Console.WriteLine($"  [Tool] WebSearch: \"{query}\"");
    var results = query.ToLowerInvariant() switch
    {
        var q when q.Contains("quantum computing") && q.Contains("2026") =>
            """
            1. In 2026, IBM unveiled a 10,000-qubit processor codenamed "Kookaburra" enabling practical error correction.
            2. Google DeepMind demonstrated quantum advantage in drug-discovery molecular simulations.
            3. Microsoft announced Azure Quantum achieved topological qubit stability at room temperature.
            4. China's USTC reported a 1,200-qubit photonic quantum computer breaking previous records.
            """,
        var q when q.Contains("quantum") && q.Contains("application") =>
            """
            1. Quantum computing applications in 2026 focus on cryptography, materials science, and logistics optimization.
            2. Financial institutions are piloting quantum algorithms for portfolio optimization.
            3. Pharmaceutical companies use quantum simulations to model protein folding.
            """,
        var q when q.Contains("quantum") && q.Contains("challenge") =>
            """
            1. Key challenges remain: qubit decoherence, error rates, and the need for cryogenic cooling.
            2. The talent gap in quantum engineering is a major bottleneck for industry adoption.
            3. Standardization of quantum programming frameworks is still in progress.
            """,
        _ =>
            $"""
            1. General information about "{query}": this is a rapidly evolving field.
            2. Multiple research institutions and companies are investing heavily.
            3. Public interest and government funding continue to grow worldwide.
            """
    };
    return results;
}

[Description("Save a note to the research notebook for later reference when summarizing findings.")]
string SaveNote([Description("The note content to save")] string content)
{
    Console.WriteLine($"  [Tool] SaveNote: \"{content[..Math.Min(content.Length, 60)]}...\"");
    notes.Add(content);
    return $"Note saved. You now have {notes.Count} note(s).";
}

[Description("Retrieve all saved notes from the research notebook.")]
string GetNotes()
{
    Console.WriteLine("  [Tool] GetNotes");
    if (notes.Count == 0)
        return "No notes saved yet.";
    return string.Join("\n---\n", notes.Select((n, i) => $"Note {i + 1}: {n}"));
}

// --- Agent Setup ---

var topic = args.Length > 0 ? string.Join(' ', args) : "quantum computing breakthroughs in 2026";

Console.WriteLine($"Research Agent Starting...");
Console.WriteLine($"Topic: {topic}");
Console.WriteLine(new string('-', 60));

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY") ?? "demo-key";
var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o";

IChatClient client = new OpenAI.OpenAIClient(apiKey)
    .GetChatClient(model)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

var chatOptions = new ChatOptions
{
    Tools =
    [
        AIFunctionFactory.Create(WebSearch),
        AIFunctionFactory.Create(SaveNote),
        AIFunctionFactory.Create(GetNotes),
    ]
};

var systemPrompt = $"""
    You are a research agent. Your goal is to thoroughly research the following topic and produce a summary.

    Topic: {topic}

    Instructions:
    1. Use the WebSearch tool multiple times with different queries to gather diverse information.
    2. Use the SaveNote tool to record important findings as you go.
    3. After gathering enough information, use GetNotes to review your research.
    4. Finally, provide a well-structured summary of your findings to the user.

    Be thorough: search for recent developments, applications, and challenges.
    """;

var messages = new List<ChatMessage>
{
    new(ChatRole.System, systemPrompt),
    new(ChatRole.User, $"Please research the topic \"{topic}\" and provide a comprehensive summary.")
};

// --- Agent Loop ---

Console.WriteLine("\nAgent is researching...\n");

var response = await client.GetResponseAsync(messages, chatOptions);

Console.WriteLine(new string('=', 60));
Console.WriteLine("RESEARCH SUMMARY");
Console.WriteLine(new string('=', 60));
Console.WriteLine(response.Text);
Console.WriteLine(new string('=', 60));

if (notes.Count > 0)
{
    Console.WriteLine($"\n[Agent saved {notes.Count} note(s) during research]");
}

