+var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o";
+
+IChatClient client = new OpenAI.OpenAIClient(apiKey)
+    .GetChatClient(model)
+    .AsIChatClient()
+    .AsBuilder()
+    .UseFunctionInvocation()
+    .Build();
+
+var chatOptions = new ChatOptions
+{
+    Tools =
+    [
+        AIFunctionFactory.Create(WebSearch),
+        AIFunctionFactory.Create(SaveNote),
+        AIFunctionFactory.Create(GetNotes),
+    ]
+};
+
+var systemPrompt = $"""
+    You are a research agent. Your goal is to thoroughly research the following topic and produce a summary.
+
+    Topic: {topic}
+
+    Instructions:
+    1. Use the WebSearch tool multiple times with different queries to gather diverse information.
+    2. Use the SaveNote tool to record important findings as you go.
+    3. After gathering enough information, use GetNotes to review your research.
+    4. Finally, provide a well-structured summary of your findings to the user.
+
+    Be thorough: search for recent developments, applications, and challenges.
+    """;
+
+var messages = new List<ChatMessage>
+{
+    new(ChatRole.System, systemPrompt),
+    new(ChatRole.User, $"Please research the topic \"{topic}\" and provide a comprehensive summary.")
+};
+
+// --- Agent Loop ---
+
+Console.WriteLine("\nAgent is researching...\n");
+
+var response = await client.GetResponseAsync(messages, chatOptions);
+
+Console.WriteLine(new string('=', 60));
+Console.WriteLine("RESEARCH SUMMARY");
+Console.WriteLine(new string('=', 60));
+Console.WriteLine(response.Text);
+Console.WriteLine(new string('=', 60));
+
+if (notes.Count > 0)
+{
+    Console.WriteLine($"\n[Agent saved {notes.Count} note(s) during research]");
+}
